// 1) Exchanges: keep valid tickers, prefer "green" trust score when available
const tous = $('Prix BTC par plateforme').all().map(i => i.json)
  .filter(t => !t.is_stale && !t.is_anomaly && t.converted_last?.usd)
  .map(t => ({
    plateforme: t.market?.name,
    paire: `${t.base}/${t.target}`,
    prix_usd: t.converted_last.usd,
    volume_usd: Math.round(t.converted_volume?.usd || 0),
    spread_pct: t.bid_ask_spread_percentage,
    confiance: t.trust_score || 'inconnue'
  }));
const verts = tous.filter(t => t.confiance === 'green');
const tickers = (verts.length ? verts : tous)
  .sort((a, b) => ((a.spread_pct ?? 99) - (b.spread_pct ?? 99)) || (b.volume_usd - a.volume_usd))
  .slice(0, 10);

// 2) Market context
const marche = $('Marché top 10').all().map(i => i.json).map(c => ({
  coin: c.symbol?.toUpperCase(),
  prix: c.current_price,
  var_1h: c.price_change_percentage_1h_in_currency?.toFixed(2),
  var_24h: c.price_change_percentage_24h_in_currency?.toFixed(2),
  var_7j: c.price_change_percentage_7d_in_currency?.toFixed(2)
}));

// 3) News from the last 12 hours
const limite = Date.now() - 12 * 3600 * 1000;
const actus = [...$('Actus CoinDesk').all(), ...$('Actus Cointelegraph').all()]
  .map(i => i.json)
  .filter(a => new Date(a.isoDate || a.pubDate).getTime() > limite)
  .slice(0, 20)
  .map(a => `- ${a.title} (${a.link})`);

return [{ json: {
  plateformes: JSON.stringify(tickers, null, 1),
  marche: JSON.stringify(marche, null, 1),
  actus: actus.join('\n') || 'Aucune actu récente'
} }];

