// Garde la dernière analyse en mémoire pour l'application
const sd = $getWorkflowStaticData('global');
const prep = $('Préparer les données').first().json;
let plateformes = [], marche = [];
try { plateformes = JSON.parse(prep.plateformes); } catch (e) {}
try { marche = JSON.parse(prep.marche); } catch (e) {}
sd.derniere = {
  date: new Date().toISOString(),
  analyse: $json.output,
  plateformes: plateformes.slice(0, 5),
  marche
};
return $input.all();

// Prépare un message pour chaque abonné
const sd = $getWorkflowStaticData('global');
const abonnes = sd.abonnes && sd.abonnes.length ? sd.abonnes : ['YOUR_TELEGRAM_CHAT_ID'];
const output = $json.output;
return abonnes.map(chatId => ({ json: { chatId, output } }));

// Construit la page de l'application à partir de la dernière analyse
const d = $getWorkflowStaticData('global').derniere;
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const fmt = s => esc(s).replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\n/g,'<br>');
const num = (n, dec = 2) => n == null ? '–' : Number(n).toLocaleString('fr-FR', { maximumFractionDigits: dec });
const couleur = v => v == null ? '' : (Number(v) >= 0 ? 'up' : 'down');

let contenu;
if (!d) {
  contenu = `<div class="card"><h2>⏳ Première analyse en préparation</h2><p>L'agent publie une nouvelle analyse toutes les 2 heures. Revenez un peu plus tard.</p></div>`;
} else {
  const date = new Date(d.date).toLocaleString('fr-FR', { timeZone: 'Europe/Paris', dateStyle: 'medium', timeStyle: 'short' });
  const lignesPlat = (d.plateformes || []).map((p, i) => `
    <tr><td>${i + 1}. ${esc(p.plateforme)}</td><td>${esc(p.paire)}</td>
    <td class="r">${num(p.prix_usd, 0)} $</td><td class="r">${num(p.spread_pct, 3)} %</td></tr>`).join('');
  const lignesMarche = (d.marche || []).map(c => `
    <tr><td><b>${esc(c.coin)}</b></td><td class="r">${num(c.prix)} $</td>
    <td class="r ${couleur(c.var_24h)}">${c.var_24h ?? '–'} %</td>
    <td class="r ${couleur(c.var_7j)}">${c.var_7j ?? '–'} %</td></tr>`).join('');
  contenu = `
    <p class="maj">Mise à jour : ${date}</p>
    <div class="card"><h2>🧠 Analyse de l'agent</h2><div class="analyse">${fmt(d.analyse)}</div></div>
    <div class="card"><h2>🏦 Plateformes BTC (plus petit écart d'abord)</h2>
      <table><tr><th>Plateforme</th><th>Paire</th><th class="r">Prix</th><th class="r">Spread</th></tr>${lignesPlat}</table></div>
    <div class="card"><h2>📊 Marché – Top 10</h2>
      <table><tr><th>Crypto</th><th class="r">Prix</th><th class="r">24h</th><th class="r">7j</th></tr>${lignesMarche}</table></div>`;
}

const html = `<!doctype html>
<html lang="fr"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-title" content="Farah Crypto">
<meta name="theme-color" content="#0f1420">
<title>Farah Crypto</title>
<style>
  :root { --bg:#0f1420; --card:#181f2e; --txt:#e8ecf3; --muted:#8a94a8; --line:#262f42; --up:#2ecc8f; --down:#ff6b6b; --accent:#f5b942; }
  * { box-sizing:border-box; }
  body { margin:0; background:var(--bg); color:var(--txt); font:15px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; }
  header { padding:22px 16px 6px; max-width:720px; margin:auto; }
  h1 { margin:0; font-size:24px; } h1 span { color:var(--accent); }
  .sous { color:var(--muted); margin:2px 0 0; font-size:13px; }
  main { padding:8px 16px 32px; max-width:720px; margin:auto; }
  .maj { color:var(--muted); font-size:13px; margin:4px 0 12px; }
  .card { background:var(--card); border:1px solid var(--line); border-radius:14px; padding:14px 16px; margin-bottom:14px; }
  h2 { font-size:16px; margin:0 0 10px; }
  .analyse { font-size:15px; }
  table { width:100%; border-collapse:collapse; font-size:14px; }
  th { text-align:left; color:var(--muted); font-weight:500; font-size:12px; padding:4px 4px 6px; border-bottom:1px solid var(--line); }
  td { padding:7px 4px; border-bottom:1px solid var(--line); }
  tr:last-child td { border-bottom:none; }
  .r { text-align:right; } .up { color:var(--up); } .down { color:var(--down); }
  .btn { display:block; text-align:center; background:var(--accent); color:#111; font-weight:600; text-decoration:none; padding:12px; border-radius:12px; margin:6px 0 14px; }
  footer { color:var(--muted); font-size:12px; text-align:center; padding:0 16px 28px; max-width:720px; margin:auto; }
</style></head>
<body>
<header><h1>Farah <span>Crypto</span></h1><p class="sous">Veille crypto automatique par IA · toutes les 2h</p></header>
<main>
  <a class="btn" href="">🔄 Actualiser</a>
  ${contenu}
</main>
<footer>⚠️ Analyse générée automatiquement à partir de données publiques (CoinGecko, CoinDesk, Cointelegraph). Ce n'est pas un conseil financier.</footer>
</body></html>`;

return [{ json: { html } }];

// Inscrit / désinscrit les personnes qui écrivent au bot
const sd = $getWorkflowStaticData('global');
sd.abonnes = sd.abonnes || ['YOUR_TELEGRAM_CHAT_ID'];
const msg = $json.message || {};
const chatId = String(msg.chat?.id || '');
const texte = (msg.text || '').trim().toLowerCase();
let reponse;
if (!chatId) return [];
if (texte.startsWith('/stop')) {
  sd.abonnes = sd.abonnes.filter(id => id !== chatId);
  reponse = "🔕 Tu es désinscrit(e). Envoie /start pour te réabonner.";
} else {
  if (!sd.abonnes.includes(chatId)) sd.abonnes.push(chatId);
  reponse = "✅ Bienvenue sur Farah Crypto !\n\nTu recevras une analyse du marché crypto toutes les 2 heures.\n\nEnvoie /stop pour ne plus recevoir les messages.\n\n⚠️ Analyse automatique, pas un conseil financier.";
}
return [{ json: { chatId, reponse } }];
